const {esc,api,toast,modalWide,closeModal}=window;
const c05status=s=>['completed','exported','reviewed','applied','accepted'].includes(s)?'good':['rejected','cancelled','stale'].includes(s)?'bad':['proposed','draft','in_progress'].includes(s)?'warn':'info';
function c05actions(rows){if(!rows.length)return '<div class="empty">当前没有开放行动。点击“刷新行动建议”按当前证据和 Decision Context 重新推导。</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>优先级</th><th>候选人</th><th>动作</th><th>原因</th><th>状态</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${x.priority}</strong></td><td class="mono">${esc(String(x.candidate_id).slice(0,8))}</td><td>${esc(x.action_type)}${x.criterion_key?`<div class="subtle">${esc(x.criterion_key)}</div>`:''}</td><td>${esc(x.reason_text)}</td><td><span class="status ${c05status(x.status)}">${esc(x.status)}</span></td><td class="right">${x.status==='proposed'?`<button class="btn small" onclick="c05transition('${x.id}','accept',${x.expected_state_version})">接受</button>`:''}${x.status==='accepted'?`<button class="btn small" onclick="c05transition('${x.id}','start',${x.expected_state_version})">开始</button>`:''}${['accepted','in_progress'].includes(x.status)?` <button class="btn small primary" onclick="c05complete('${x.id}',${x.expected_state_version})">完成</button>`:''}${x.status==='completed'?`<button class="btn small" onclick="c05stageLearning('${x.id}')">沉淀反馈</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function c05feedback(rows){if(!rows.length)return '<div class="empty">尚无人工反馈记录。</div>';return `<div class="quick-list">${rows.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.classification?.feedback_type||x.source_type)} · ${esc(String(x.candidate_id||'项目级').slice(0,12))}</div><div class="quick-note">事实 ${(x.classification?.candidate_facts||[]).length} · 岗位需求 ${(x.classification?.job_requirements||[]).length} · 冲突 ${(x.classification?.conflicts||[]).length}</div></div><div class="actions"><span class="status ${c05status(x.status)}">${esc(x.status)}</span>${x.status==='draft'?`<button class="btn small" onclick="c05ReviewFeedback('${x.id}','review')">已复核</button>${x.candidate_id?`<button class="btn small primary" onclick="c05ReviewFeedback('${x.id}','apply_candidate_facts')">应用候选人事实</button>`:''}<button class="btn small danger" onclick="c05ReviewFeedback('${x.id}','reject')">拒绝</button>`:''}</div></div>`).join('')}</div>`}
function c05learning(rows,curation){return `<div class="two"><section><h4>知识反馈草稿</h4>${rows.length?`<div class="quick-list">${rows.map(x=>`<div class="quick-item"><div><strong>${esc(x.title)}</strong><div class="quick-note">${esc(x.summary)}</div></div><div class="actions"><span class="status ${c05status(x.status)}">${esc(x.status)}</span>${x.status==='draft'?`<button class="btn small" onclick="c05PromoteLearning('${x.id}')">送治理队列</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty">只有人工确认完成的行动结果，才能生成知识反馈草稿。</div>'}</section><section><h4>Knowledge Governance</h4>${curation.length?`<div class="quick-list">${curation.map(x=>`<div class="quick-item"><div><strong>${esc(x.title)}</strong><div class="quick-note">${esc(x.source_kind)} · ${esc(x.proposed_action)}</div></div><div class="actions"><span class="status ${c05status(x.status)}">${esc(x.status)}</span>${x.status==='draft'?`<button class="btn small" onclick="c05ReviewCuration('${x.id}',${x.expected_state_version})">人工治理</button>`:''}${x.status==='reviewed'?`<button class="btn small primary" onclick="c05ExportCuration('${x.id}')">导出变更包</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty">治理队列为空。Active Knowledge DB 不会被运行时反馈直接修改。</div>'}</section></div>`}
window.operationsLearningTab=async(el,p)=>{window.__c05ProjectId=p.project_id;const d=await api(`/api/v1/projects/${p.project_id}/operations-learning`);window.__c05Data=d;const plan=d.planning.plan||{},ass=d.planning.assessment||{},oa=d.planning.open_actions||{};el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><div><h3>运营、反馈与学习闭环</h3><span class="subtle">恢复 0.8.x 的 Decision Operations / Feedback / Planning / Knowledge Governance。运营优先级 ≠ 招聘排名。</span></div><button class="btn primary" onclick="c05RecommendActions()">刷新行动建议</button></div><div class="grid kpi">${[['招聘目标',plan.target_hires||1,'目标 HC'],['剩余 HC',d.planning.remaining_hires||0,'扣除 hired / accepted offer'],['可比较候选人',ass.publishable_count||0,'证据闭合后才进入比较'],['开放行动',oa.total||0,'必须人工接受/完成']].map(x=>`<div class="kpi-card"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${x[1]}</div><div class="kpi-note">${x[2]}</div></div>`).join('')}</div><div class="two"><section class="panel"><div class="panel-head"><h3>Recruitment Plan</h3><button class="btn small" onclick="c05EditPlan()">编辑</button></div><div class="panel-body"><div class="quick-list"><div class="quick-item"><span>负责人</span><strong>${esc(plan.owner||'未设置')}</strong></div><div class="quick-item"><span>目标日期</span><strong>${esc(plan.target_date||'未设置')}</strong></div><div class="quick-item"><span>平均证据覆盖</span><strong>${Math.round(Number(ass.average_evidence_coverage||0)*100)}%</strong></div><div class="quick-item"><span>Decision Ready</span><strong>${ass.decision_ready_count||0}</strong></div></div>${d.planning.bottlenecks?.length?`<div class="divider"></div>${d.planning.bottlenecks.map(b=>`<div class="status ${b.severity==='high'?'bad':'warn'}" style="display:block;margin:6px 0">${esc(b.text)}</div>`).join('')}`:''}</div></section><section class="panel"><div class="panel-head"><h3>人工反馈入口</h3></div><div class="panel-body"><div class="field"><label>候选人 ID（项目级岗位反馈可留空）</label><input id="c05-feedback-candidate" class="input" placeholder="candidate id"></div><div class="field" style="margin-top:8px"><label>反馈文本</label><textarea id="c05-feedback-text" class="textarea" placeholder="候选人事实：...&#10;岗位需求：...&#10;冲突：..."></textarea></div><div class="actions" style="margin-top:8px"><button class="btn primary" onclick="c05CreateFeedback()">保存并分类</button></div></div></section></div><section class="panel" style="margin-top:12px"><div class="panel-head"><h3>Decision Operations</h3><span class="subtle">建议动作不会自动推进候选人，也不会输出 Hire/Reject。</span></div><div class="panel-body">${c05actions(d.actions||[])}</div></section><section class="panel" style="margin-top:12px"><div class="panel-head"><h3>Feedback Records</h3></div><div class="panel-body">${c05feedback(d.feedback||[])}</div></section><section class="panel" style="margin-top:12px"><div class="panel-head"><h3>Knowledge Learning Loop</h3><span class="subtle">运行时反馈 → 草稿 → 人工治理 → 导出变更包；不会直接污染 Gold/active DB。</span></div><div class="panel-body">${c05learning(d.knowledge_feedback||[],d.curation||[])}</div></section>`}
window.c05Reload=()=>window.setProjectTab?.('ops');
window.c05RecommendActions=async()=>{try{await api(`/api/v1/projects/${window.__c05ProjectId}/decision-actions/recommend`,{method:'POST',body:'{}'});toast('行动建议已按当前 Decision Context 刷新');c05Reload()}catch(e){toast(e.message,true)}};
window.c05EditPlan=()=>{const p=window.__c05Data?.planning?.plan||{};modalWide('编辑 Recruitment Plan',`<div class="form-grid"><div class="field"><label>目标 HC</label><input id="c05-plan-target" type="number" min="1" class="input" value="${Number(p.target_hires||1)}"></div><div class="field"><label>目标日期</label><input id="c05-plan-date" class="input" value="${esc(p.target_date||'')}"></div><div class="field"><label>负责人</label><input id="c05-plan-owner" class="input" value="${esc(p.owner||'')}"></div><div class="field"><label>来源渠道（逗号分隔）</label><input id="c05-plan-channels" class="input" value="${esc((p.source_channels||[]).join(','))}"></div><div class="field full"><label>计划说明</label><textarea id="c05-plan-notes" class="textarea">${esc(p.notes||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="c05SavePlan()">保存</button>`)};
window.c05SavePlan=async()=>{try{await api(`/api/v1/projects/${window.__c05ProjectId}/planning`,{method:'PUT',body:JSON.stringify({target_hires:Number(document.querySelector('#c05-plan-target').value||1),target_date:document.querySelector('#c05-plan-date').value,owner:document.querySelector('#c05-plan-owner').value,source_channels:document.querySelector('#c05-plan-channels').value.split(',').map(x=>x.trim()).filter(Boolean),notes:document.querySelector('#c05-plan-notes').value})});closeModal();toast('招聘计划已保存');c05Reload()}catch(e){toast(e.message,true)}};
window.c05transition=async(id,t,v)=>{try{await api(`/api/v1/decision-actions/${id}/transition`,{method:'POST',body:JSON.stringify({transition:t,actor:'human',expected_state_version:v,reason:'人工操作'})});c05Reload()}catch(e){toast(e.message,true)}};
window.c05complete=async(id,v)=>{const result=prompt('记录该动作的人工确认结果：','已核实');if(result===null)return;const learning=prompt('可选：这次执行有什么可沉淀的招聘/核实经验？留空则不生成知识反馈。','');const outcome={human_confirmed:true,result};if(learning?.trim())outcome.knowledge_feedback={feedback_type:'operational_learning',title:'招聘执行反馈',summary:learning.trim(),evidence_refs:[]};try{await api(`/api/v1/decision-actions/${id}/transition`,{method:'POST',body:JSON.stringify({transition:'complete',actor:'human',expected_state_version:v,outcome,reason:'人工确认完成'})});c05Reload()}catch(e){toast(e.message,true)}};
window.c05stageLearning=async id=>{try{await api(`/api/v1/decision-actions/${id}/knowledge-feedback`,{method:'POST',body:JSON.stringify({actor:'human'})});toast('已生成知识反馈草稿');c05Reload()}catch(e){toast(e.message,true)}};
window.c05CreateFeedback=async()=>{try{const text=document.querySelector('#c05-feedback-text').value.trim();if(!text)throw new Error('请填写反馈文本');await api(`/api/v1/projects/${window.__c05ProjectId}/feedback`,{method:'POST',body:JSON.stringify({candidate_id:document.querySelector('#c05-feedback-candidate').value.trim()||null,text,source_type:'manual',actor:'human'})});toast('反馈已保存并分类');c05Reload()}catch(e){toast(e.message,true)}};
window.c05ReviewFeedback=async(id,action)=>{const reason=prompt('人工复核说明：','已人工复核')||'';try{await api(`/api/v1/feedback/${id}/review`,{method:'POST',body:JSON.stringify({action,reviewer:'human',reason})});c05Reload()}catch(e){toast(e.message,true)}};
window.c05PromoteLearning=async id=>{try{await api(`/api/v1/knowledge-feedback/${id}/promote`,{method:'POST',body:JSON.stringify({actor:'human'})});toast('已送入 Knowledge Governance');c05Reload()}catch(e){toast(e.message,true)}};
window.c05ReviewCuration=async(id,v)=>{const action=prompt('治理动作：confirm_alias / confirm_specialization / confirm_competency_alias / create_canonical / keep_unknown / defer / reject','keep_unknown');if(action===null)return;const reason=prompt('治理理由：','人工复核')||'';try{await api(`/api/v1/knowledge-curation/${id}/review`,{method:'POST',body:JSON.stringify({action,reviewer:'human',reason,expected_state_version:v})});c05Reload()}catch(e){toast(e.message,true)}};
window.c05ExportCuration=async id=>{try{const r=await api(`/api/v1/knowledge-curation/${id}/export`,{method:'POST',body:JSON.stringify({actor:'human'})});toast(`已导出治理变更包：${r.export_file}；Active Knowledge 未改动`);c05Reload()}catch(e){toast(e.message,true)}};
